const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });

function page(isEditor, editorKey) {
  const admin = isEditor ? `<section class="card form"><h2>대진 조건</h2><div class="twocol"><label>코트 수<input id="courts" type="number" value="3" min="1" max="20"></label><label>라운드 수<input id="rounds" type="number" value="4" min="1" max="20"></label></div><label>참가자 이름</label><textarea id="names" placeholder="한 줄에 한 명씩 입력하세요"></textarea><p class="hint">쉼표 또는 줄바꿈으로 구분할 수 있습니다.</p><button id="make">대진 만들기</button><button class="sub" id="save">현재 대진 저장</button><p id="saveMsg" class="hint"></p></section>` : `<section class="card viewer"><span class="pill">읽기 전용</span><h2>오늘의 대진표</h2><p>운영진이 저장한 최신 대진을 확인할 수 있습니다.</p><button class="sub" id="refresh">새로고침</button></section>`;
  return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>콕끼리 | 배드민턴 대진표</title><style>:root{--g:#12683f;--dark:#0b452b;--lime:#d7f368;--line:#dce8df;--muted:#63756b}*{box-sizing:border-box}body{margin:0;background:#f5f9f6;color:#19271f;font-family:Arial,'Malgun Gothic',sans-serif;font-size:16px}header{padding:25px max(20px,calc((100% - 1080px)/2));background:var(--dark);color:white}.brand{font-size:1.5rem;font-weight:800}.brand b{display:inline-grid;place-items:center;width:31px;height:31px;border-radius:9px;background:var(--lime);color:var(--dark);margin-right:9px}header p{margin:5px 0 0 40px;color:#d8e9df;font-size:.9rem}main{max-width:1080px;margin:auto;padding:30px 20px 64px}.intro h1{margin:0;font-size:2rem;letter-spacing:-.05em}.intro p{color:var(--muted);margin:7px 0 24px}.grid{display:grid;grid-template-columns:360px 1fr;gap:22px;align-items:start}.card{background:white;border:1px solid var(--line);border-radius:17px;padding:22px;box-shadow:0 5px 18px #1a54330b}h2{margin:0 0 16px;font-size:1.14rem}label{display:block;margin:14px 0 7px;font-weight:700;font-size:.9rem}input,textarea{width:100%;padding:11px;border:1px solid #c3d2c8;border-radius:10px;font:inherit}textarea{height:220px;resize:vertical;line-height:1.6}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:12px}.twocol label{margin-top:0}.hint{color:var(--muted);font-size:.84rem}button{width:100%;padding:13px;margin-top:12px;border:0;border-radius:10px;background:var(--g);color:white;font:inherit;font-weight:800;cursor:pointer}.sub{background:#eaf3ed;color:var(--dark)}.pill{display:inline-block;background:var(--lime);border-radius:99px;padding:4px 9px;font-size:.78rem;font-weight:800}.results{min-height:460px}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding:0 0 16px}.head h2{margin:0}.meta{font-size:.82rem;color:var(--muted)}.empty{text-align:center;color:var(--muted);padding:110px 12px}.round{margin-top:21px}.round h3{font-size:1rem;margin:0 0 10px}.round h3 span{font-size:.78rem;background:var(--lime);border-radius:99px;padding:4px 8px;margin-right:7px}.matches{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.match{border:1px solid var(--line);border-left:4px solid var(--g);border-radius:9px;padding:11px;background:#fcfefc}.court{font-size:.78rem;color:var(--g);font-weight:800}.players{font-weight:700;margin-top:6px;line-height:1.6}.vs{font-size:.72rem;color:#976233;margin:0 5px}.rest{background:#fff7ec;border-radius:8px;padding:9px;margin-top:9px;font-size:.86rem;color:#805425}@media(max-width:760px){.grid{grid-template-columns:1fr}.matches{grid-template-columns:1fr}.intro h1{font-size:1.7rem}}</style></head><body><header><div class="brand"><b>⌁</b>콕끼리</div><p>배드민턴 모임 대진표</p></header><main><section class="intro"><h1>${isEditor ? '대진을 만들고 공유하세요' : '저장된 대진표를 확인하세요'}</h1><p>${isEditor ? '대진 생성 후 저장하면 뷰어 링크에 바로 반영됩니다.' : '운영진이 저장한 최신 대진입니다.'}</p></section><div class="grid">${admin}<section class="card results"><div class="head"><h2>대진표</h2><span class="meta" id="meta">불러오는 중</span></div><div id="out" class="empty">🏸<br><br>저장된 대진표를 불러오는 중입니다.</div></section></div></main><script>const EDITOR=${JSON.stringify(isEditor ? editorKey : '')};let data=null;const el=id=>document.getElementById(id);const key=(a,b)=>[a,b].sort().join('|');const shuffle=a=>[...a].sort(()=>Math.random()-.5);function make(names,courts,rounds){let ps=new Map(),os=new Map(),play=new Map(names.map(n=>[n,0])),all=[];for(let r=1;r<=rounds;r++){let cap=Math.min(courts,Math.floor(names.length/4)),best;for(let t=0;t<450;t++){let p=shuffle(names).sort((a,b)=>play.get(a)-play.get(b)),use=p.slice(0,cap*4),score=0,g=[];for(let i=0;i<use.length;i+=4){let x=use.slice(i,i+4),[a,b,c,d]=x;score+=(ps.get(key(a,b))||0)*30+(ps.get(key(c,d))||0)*30;for(const u of[a,b])for(const v of[c,d])score+=(os.get(key(u,v))||0)*8;g.push(x)}if(!best||score<best.s)best={g,rest:p.slice(cap*4),s:score}}best.g.forEach(([a,b,c,d])=>{[[a,b],[c,d]].forEach(([x,y])=>ps.set(key(x,y),(ps.get(key(x,y))||0)+1));for(const x of[a,b])for(const y of[c,d])os.set(key(x,y),(os.get(key(x,y))||0)+1);[a,b,c,d].forEach(n=>play.set(n,play.get(n)+1))});all.push({round:r,g:best.g,rest:best.rest})}return all}function draw(){let out=el('out');if(!data||!data.schedule||!data.schedule.length){out.className='empty';out.innerHTML='🏸<br><br>아직 저장된 대진표가 없습니다.';el('meta').textContent='대기 중';return}out.className='';out.innerHTML=data.schedule.map(x=>'<section class="round"><h3><span>'+x.round+'R</span>라운드 '+x.round+'</h3><div class="matches">'+x.g.map((m,i)=>'<article class="match"><div class="court">'+(i+1)+'번 코트</div><div class="players">'+m[0]+' · '+m[1]+'<b class="vs">VS</b>'+m[2]+' · '+m[3]+'</div></article>').join('')+'</div>'+(x.rest.length?'<div class="rest">휴식: '+x.rest.join(', ')+'</div>':'')+'</section>').join('');el('meta').textContent=data.updatedAt?'최종 저장 '+new Date(data.updatedAt).toLocaleString('ko-KR'):'임시 대진'}async function load(){let r=await fetch('/api/schedule');data=(await r.json()).data||null;draw();if(EDITOR&&data){el('courts').value=data.courts;el('rounds').value=data.rounds;el('names').value=data.names.join('\\n')}}async function save(){if(!data)return;let r=await fetch('/api/schedule',{method:'PUT',headers:{'content-type':'application/json','x-kokkiri-editor':EDITOR},body:JSON.stringify(data)});let v=await r.json();el('saveMsg').textContent=r.ok?'저장되었습니다. 뷰어 링크에 반영됐습니다.':v.error||'저장에 실패했습니다.';if(r.ok){data=v.data;draw()}}if(EDITOR){el('make').onclick=()=>{let names=[...new Set(el('names').value.split(/[\\n,]+/).map(x=>x.trim()).filter(Boolean))],courts=+el('courts').value,rounds=+el('rounds').value;if(names.length<4||!courts||!rounds){alert('참가자 4명 이상, 코트 수와 라운드 수를 확인해주세요.');return}data={names,courts,rounds,schedule:make(names,courts,rounds),updatedAt:null};draw()};el('save').onclick=save}else el('refresh').onclick=load;load();</script></body></html>`;
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const editorKey = env.EDITOR_KEY;
    const isEditor = url.pathname === `/operate-${editorKey}`;
    if (url.pathname === "/api/schedule") {
      if (request.method === "GET") {
        const row = await env.DB.prepare("SELECT payload, updated_at FROM schedules WHERE id = 1").first();
        return json({ data: row ? { ...JSON.parse(row.payload), updatedAt: row.updated_at } : null });
      }
      if (request.method === "PUT") {
        if (!editorKey || request.headers.get("x-kokkiri-editor") !== editorKey) return json({ error: "수정 권한이 없습니다." }, 403);
        const data = await request.json();
        if (!Array.isArray(data.names) || !Array.isArray(data.schedule) || data.names.length < 4) return json({ error: "대진 데이터가 올바르지 않습니다." }, 400);
        const updatedAt = new Date().toISOString();
        await env.DB.prepare("INSERT INTO schedules (id, payload, updated_at) VALUES (1, ?, ?) ON CONFLICT(id) DO UPDATE SET payload = excluded.payload, updated_at = excluded.updated_at").bind(JSON.stringify({ names: data.names, courts: data.courts, rounds: data.rounds, schedule: data.schedule }), updatedAt).run();
        return json({ data: { ...data, updatedAt } });
      }
      return json({ error: "허용되지 않은 요청입니다." }, 405);
    }
    return new Response(page(isEditor, editorKey), { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" } });
  }
};
